-- migration_v659_engine_network_proxy_codes: lỗi mạng / proxy khi mở trang Facebook, lỗi proxy Zalo. Anh chốt 26/11/2026 qua hộp chọn (ca hộp thư lỗi câu 6282, cùng nhóm
-- 6281 / 3590 / 638 / 633 / 3484). Sinh bằng scripts/build-v659-sql.cjs từ bản sao danh mục production đọc 26/11, không sửa tay.
--   * Facebook trước lúc gửi: ERR_CONNECTION_* / ERR_TIMED_OUT / ERR_SOCKET_NOT_CONNECTED / ERR_TOO_MANY_RETRIES / ERR_NAME_NOT_RESOLVED /
--     ERR_ADDRESS_UNREACHABLE → NET01 (trước đây FB44: đóng data chưa đăng, cộng chuỗi).
--   * NET01 Facebook như Zalo (V500 Q5): data về hàng đợi, khoá thao tác Facebook của tài khoản 5 phút, cộng chuỗi, 4 lần liền tạm dừng.
--   * Câu NET01 Facebook và Zalo: "Kết nối mạng bị gián đoạn, tạm ngưng tài khoản tới {until}"; tên mã NET01 (câu chờ) "Kết nối mạng bị gián đoạn".
--   * Lỗi proxy chắc chắn trước lúc gửi (Facebook, Zalo) → NET02 như NET01, câu "Proxy của tài khoản không kết nối được, tạm ngưng tài khoản tới {until}"; câu dừng
--     NET02 nối "Kiểm tra lại proxy của tài khoản rồi bấm Tiếp tục chiến dịch." (vá aka_agent_engine_report_v1).
--   * Zalo lỗi proxy lúc đang gửi → NET04 mới, y UNK01; tìm SĐT lỗi proxy lúc đang chạy → NET02.
--   * Bước danh tính Page: Desktop bản sau gửi lỗi mở trang của bước này như bước mở trang, nên đi theo luật trên (không cần dòng riêng).
BEGIN;
SET LOCAL lock_timeout = '3s';

DO $pre$
DECLARE v_n int;
BEGIN
  IF EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE name LIKE 'migration_v659_%') THEN
    RAISE EXCEPTION 'V659: sổ migration đã có migration_v659_%%, không chạy lại';
  END IF;
  IF EXISTS (SELECT 1 FROM public.auto_error WHERE error_code = 'err_proxy_unknown_delivery' OR public_code = 'NET04') THEN
    RAISE EXCEPTION 'V659: đã có mã NET04';
  END IF;
  IF (SELECT count(*) FROM public.auto_error WHERE is_active AND NOT is_delete AND (error_code, public_code) IN
      (('err_network_offline', 'NET01'), ('err_proxy_failed', 'NET02'), ('err_engine_unknown_delivery', 'UNK01'), ('err_fb_identity_switch_failed', 'FB06'))) <> 4 THEN
    RAISE EXCEPTION 'V659: thiếu mã NET01 / NET02 / UNK01 / FB06';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.auto_error WHERE error_code = 'err_proxy_failed' AND customer_help IS NULL) THEN
    RAISE EXCEPTION 'V659: câu bước tiếp theo của NET02 đã có';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.auto_error WHERE error_code = 'err_network_offline' AND customer_title = 'Kết nối mạng tạm thời gián đoạn') THEN
    RAISE EXCEPTION 'V659: tên mã NET01 đã đổi';
  END IF;
  SELECT count(*) INTO v_n FROM public.auto_outcome_policies WHERE error_code = 'err_network_offline' AND is_active AND NOT is_delete
    AND action_code = ANY (ARRAY['zalo_find_phone_user', 'zalo_message_stranger', 'zalo_message_friend', 'zalo_message_group', 'zalo_add_friend', 'zalo_add_group_member', 'zalo_join_group', 'zalo_join_group_link', 'zalo_tag_contact', 'zalo_change_alias', 'zalo_cancel_sent_friend_request']::text[]) AND log_template = 'Mất kết nối tới Zalo, tạm ngưng tài khoản tới {until}' AND lock_minutes = 5 AND streak_threshold = 4
    AND lock_action_codes = ARRAY['zalo_find_phone_user', 'zalo_message_stranger', 'zalo_message_friend', 'zalo_message_group', 'zalo_add_friend', 'zalo_add_group_member', 'zalo_join_group', 'zalo_join_group_link', 'zalo_tag_contact', 'zalo_change_alias', 'zalo_cancel_sent_friend_request']::text[] AND campaign_effect = 'pause' AND target_effect = 'requeue';
  IF v_n <> 11 THEN RAISE EXCEPTION 'V659: % dòng NET01 Zalo đúng bản đọc 26/11 (cần 11)', v_n; END IF;
  IF EXISTS (SELECT 1 FROM public.auto_outcome_policies WHERE is_active AND NOT is_delete AND (
       (error_code IN ('err_network_offline', 'err_proxy_failed') AND action_code LIKE 'fb\_%') OR (error_code = 'err_proxy_failed' AND action_code LIKE 'zalo\_%'))) THEN
    RAISE EXCEPTION 'V659: đã có chính sách NET01 / NET02 theo thao tác Facebook hoặc NET02 theo thao tác Zalo';
  END IF;
  SELECT count(*) INTO v_n FROM public.auto_outcome_policies WHERE error_code = 'err_engine_unknown_delivery' AND is_active AND NOT is_delete
   AND (action_code IS NULL OR action_code LIKE 'zalo\_%') AND action_code IS DISTINCT FROM 'zalo_find_phone_user' AND id = ANY (ARRAY[107, 202, 203, 204, 205, 206]::bigint[]);
  IF v_n <> 6 OR (SELECT count(*) FROM public.auto_outcome_policies WHERE error_code = 'err_engine_unknown_delivery' AND is_active AND NOT is_delete
   AND (action_code IS NULL OR action_code LIKE 'zalo\_%') AND action_code IS DISTINCT FROM 'zalo_find_phone_user') <> 6 THEN
    RAISE EXCEPTION 'V659: dòng UNK01 để chép cho NET04 khác bản đọc 26/11';
  END IF;
  SELECT count(*) INTO v_n FROM public.auto_account_actions WHERE is_active AND NOT is_delete AND code = ANY (ARRAY['fb_post_group', 'fb_post_my_profile', 'fb_comment', 'fb_message_stranger', 'fb_message_friend', 'fb_add_friend', 'fb_like_post', 'fb_post_page', 'fb_message_page_inbox_customer', 'fb_join_group', 'fb_group_invite', 'zalo_find_phone_user', 'zalo_message_stranger', 'zalo_message_friend', 'zalo_message_group', 'zalo_add_friend', 'zalo_add_group_member', 'zalo_join_group', 'zalo_join_group_link', 'zalo_tag_contact', 'zalo_change_alias', 'zalo_cancel_sent_friend_request']::text[]);
  IF v_n <> 22 THEN RAISE EXCEPTION 'V659: % thao tác để khoá (cần 22)', v_n; END IF;
  IF md5(pg_get_functiondef('public.aka_agent_engine_report_v1(bigint, uuid, jsonb, boolean, boolean)'::regprocedure)) IS DISTINCT FROM '78ed8f80c4ff7de3cae3eb3e36bb6e1b' THEN
    RAISE EXCEPTION 'V659: aka_agent_engine_report_v1 đã đổi';
  END IF;
  IF EXISTS (SELECT 1 FROM public.auto_outcome_policies WHERE source = 'v659')
     OR EXISTS (SELECT 1 FROM public.auto_outcome_signal_rules WHERE source = 'v659') THEN
    RAISE EXCEPTION 'V659: đã có dòng nguồn v659';
  END IF;
  IF EXISTS (SELECT 1 FROM public.auto_outcome_signal_rules WHERE is_active AND (
       signal_kind = 'message_like' AND pattern ILIKE ANY (ARRAY['%ERR\_CONNECTION\_%', '%ERR\_TIMED\_OUT%', '%ERR\_SOCKET\_NOT\_CONNECTED%', '%ERR\_TOO\_MANY\_RETRIES%', '%ERR\_NAME\_NOT\_RESOLVED%', '%ERR\_ADDRESS\_UNREACHABLE%', '%ERR\_PROXY%', '%ERR\_TUNNEL\_CONNECTION\_FAILED%', '%ERR\_NO\_SUPPORTED\_PROXIES%', '%ERR\_SOCKS%', '%ERR\_MANDATORY\_PROXY\_CONFIGURATION\_FAILED%', '%Proxy connection ended before receiving CONNECT response%']::text[]))) THEN
    RAISE EXCEPTION 'V659: đã có luật trùng mẫu mới';
  END IF;
END $pre$;

INSERT INTO public.auto_error (error_type, error_code, error_name, error_desc, noti_running_process, noti_campaign,
  disable_action_codes, counts_toward_limit, counts_toward_bad_target, disable_action_mode, zalo_error_codes, zalo_action_codes,
  is_active, is_delete, public_code, error_class, customer_title, customer_help)
VALUES ('engine v2', 'err_proxy_unknown_delivery', 'Proxy của tài khoản không kết nối được lúc đang gửi', 'V659 (engine v2): Proxy của tài khoản không kết nối được lúc đang gửi; xử lý y UNK01 (không gửi lại).', NULL, NULL,
  '{}', false, false, 'fixed_minutes', '{}', '{}', true, false, 'NET04', 'unknown_delivery', 'Proxy của tài khoản không kết nối được lúc đang gửi', NULL);

-- NET01: tên mã cho khách (câu chờ lúc khoá) khớp dòng tiến trình. Bộ cũ đọc noti_*, giữ nguyên.
UPDATE public.auto_error SET customer_title = 'Kết nối mạng bị gián đoạn', updated_at = now() WHERE error_code = 'err_network_offline' AND customer_title = 'Kết nối mạng tạm thời gián đoạn';

-- NET02: câu bước tiếp theo nối sau câu dừng (report_v1 vá bên dưới). Bộ cũ đọc noti_*, giữ nguyên.
UPDATE public.auto_error SET customer_help = 'Kiểm tra lại proxy của tài khoản rồi bấm Tiếp tục chiến dịch.', updated_at = now() WHERE error_code = 'err_proxy_failed' AND customer_help IS NULL;

