INSERT INTO public.auto_outcome_policies (error_code, error_class, status_id, action_code, campaign_action_id, runtime_target, detail_mode, detail_status_id, sub_status_id, log_template, campaign_note_template, quota_effect, target_streak_effect, streak_threshold, target_effect, requeue_after_minutes, remaining_steps, lock_action_codes, lock_mode, lock_minutes, lock_days, lock_time, run_effect, pace_mode, pace_seconds, campaign_effect, campaign_hold_minutes, account_effect, login_effect, streak_after_delivery, target_check_enabled, target_check_days, description, source)
SELECT 'err_proxy_unknown_delivery', error_class, status_id, action_code, campaign_action_id, runtime_target, detail_mode, detail_status_id, sub_status_id, log_template, campaign_note_template, quota_effect, target_streak_effect, streak_threshold, target_effect, requeue_after_minutes, remaining_steps, lock_action_codes, lock_mode, lock_minutes, lock_days, lock_time, run_effect, pace_mode, pace_seconds, campaign_effect, campaign_hold_minutes, account_effect, login_effect, streak_after_delivery, target_check_enabled, target_check_days,
       '[anh chốt 26/11] NET04 (proxy lúc đang gửi, Zalo): chép dòng UNK01 ' || id || ', xử lý y UNK01.', 'v659'
  FROM public.auto_outcome_policies WHERE error_code = 'err_engine_unknown_delivery' AND is_active AND NOT is_delete
   AND (action_code IS NULL OR action_code LIKE 'zalo\_%') AND action_code IS DISTINCT FROM 'zalo_find_phone_user' ORDER BY id;

-- NET01 Zalo: chỉ đổi câu (anh chốt dùng chung câu với Facebook).
UPDATE public.auto_outcome_policies SET log_template = 'Kết nối mạng bị gián đoạn, tạm ngưng tài khoản tới {until}'
 WHERE error_code = 'err_network_offline' AND is_active AND NOT is_delete AND action_code = ANY (ARRAY['zalo_find_phone_user', 'zalo_message_stranger', 'zalo_message_friend', 'zalo_message_group', 'zalo_add_friend', 'zalo_add_group_member', 'zalo_join_group', 'zalo_join_group_link', 'zalo_tag_contact', 'zalo_change_alias', 'zalo_cancel_sent_friend_request']::text[]) AND log_template = 'Mất kết nối tới Zalo, tạm ngưng tài khoản tới {until}';

