  ('zalo', NULL, 'in_flight', 'message_like', '%ERR\_MANDATORY\_PROXY\_CONFIGURATION\_FAILED%', 10, 'err_proxy_unknown_delivery', '[anh chốt 26/11] Lỗi proxy chắc chắn (ERR_MANDATORY_PROXY_CONFIGURATION_FAILED) lúc đang gửi → NET04 (xử lý y UNK01, không gửi lại).', 'v659', true),
  ('zalo', NULL, 'in_flight', 'message_like', '%Proxy connection ended before receiving CONNECT response%', 10, 'err_proxy_unknown_delivery', '[anh chốt 26/11] Lỗi proxy chắc chắn (Proxy connection ended before receiving CONNECT response) lúc đang gửi → NET04 (xử lý y UNK01, không gửi lại).', 'v659', true);

DO $patch$
DECLARE v_def text; v_new text;
BEGIN
  v_def := pg_get_functiondef('public.aka_agent_engine_report_v1(bigint, uuid, jsonb, boolean, boolean)'::regprocedure);
  IF md5(v_def) IS DISTINCT FROM '78ed8f80c4ff7de3cae3eb3e36bb6e1b' THEN RAISE EXCEPTION 'V659: aka_agent_engine_report_v1 đã đổi (md5 %)', md5(v_def); END IF;
  IF array_length(string_to_array(v_def, '        -- V558: câu bước tiếp theo của mã Facebook (anh duyệt 17/11, Q23) nối sau câu dừng; mã khác (Zalo, SYS) giữ nguyên câu cũ.
        || coalesce(''. '' || nullif(btrim((SELECT e.customer_help FROM public.auto_error e
                                          WHERE e.error_code = v_last_error_code AND e.public_code LIKE ''FB%'')), ''''), '''');'), 1) <> 2 THEN RAISE EXCEPTION 'V659: đoạn vá report_v1 không đúng một chỗ'; END IF;
  v_new := replace(v_def, '        -- V558: câu bước tiếp theo của mã Facebook (anh duyệt 17/11, Q23) nối sau câu dừng; mã khác (Zalo, SYS) giữ nguyên câu cũ.
        || coalesce(''. '' || nullif(btrim((SELECT e.customer_help FROM public.auto_error e
                                          WHERE e.error_code = v_last_error_code AND e.public_code LIKE ''FB%'')), ''''), '''');', '        -- V558: câu bước tiếp theo của mã Facebook (anh duyệt 17/11, Q23) nối sau câu dừng; mã khác (Zalo, SYS) giữ nguyên câu cũ.
        -- V659: NET02 (proxy của tài khoản, Facebook lẫn Zalo) cũng nối câu bước tiếp theo (anh chốt 26/11).
        || coalesce(''. '' || nullif(btrim((SELECT e.customer_help FROM public.auto_error e
                                          WHERE e.error_code = v_last_error_code
                                            AND (e.public_code LIKE ''FB%'' OR e.error_code = ''err_proxy_failed''))), ''''), '''');');
  IF md5(v_new) IS DISTINCT FROM 'b39e1e9dbcab4775d96779bd4799b63a' THEN RAISE EXCEPTION 'V659: thân report_v1 sau vá lệch (md5 %)', md5(v_new); END IF;
  EXECUTE v_new;
  IF md5(pg_get_functiondef('public.aka_agent_engine_report_v1(bigint, uuid, jsonb, boolean, boolean)'::regprocedure)) IS DISTINCT FROM 'b39e1e9dbcab4775d96779bd4799b63a' THEN
    RAISE EXCEPTION 'V659: thân report_v1 sau khi tạo lại lệch';
  END IF;
END $patch$;

DO $post$
DECLARE v_new jsonb; v_old jsonb; v_c jsonb; v_text text; v_rt text; v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM public.auto_outcome_signal_rules WHERE source = 'v659' AND is_active;
  IF v_n <> 30 THEN RAISE EXCEPTION 'V659 postflight: % luật mới', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.auto_outcome_policies WHERE source = 'v659' AND is_active AND NOT is_delete;
  IF v_n <> 39 THEN RAISE EXCEPTION 'V659 postflight: % dòng chính sách mới', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.auto_outcome_policies WHERE error_code = 'err_network_offline' AND is_active AND NOT is_delete AND log_template = 'Mất kết nối tới Zalo, tạm ngưng tài khoản tới {until}';
  IF v_n <> 0 THEN RAISE EXCEPTION 'V659 postflight: còn % dòng NET01 câu cũ', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.auto_error WHERE error_code = 'err_proxy_failed' AND customer_help = 'Kiểm tra lại proxy của tài khoản rồi bấm Tiếp tục chiến dịch.';
  IF v_n <> 1 THEN RAISE EXCEPTION 'V659 postflight: câu bước tiếp theo NET02'; END IF;

  -- Mỗi nhóm: mọi thao tác trong nhóm × Desktop / Fly; danh sách khoá = cả nhóm thao tác.
  FOR v_c, v_text, v_rt IN SELECT x, a, rt FROM jsonb_array_elements('[{"code":"err_network_offline","actions":["fb_post_group","fb_post_my_profile","fb_comment","fb_message_stranger","fb_message_friend","fb_add_friend","fb_like_post","fb_post_page","fb_message_page_inbox_customer","fb_join_group","fb_group_invite"],"log":"Kết nối mạng bị gián đoạn, tạm ngưng tài khoản tới {until}"},{"code":"err_proxy_failed","actions":["fb_post_group","fb_post_my_profile","fb_comment","fb_message_stranger","fb_message_friend","fb_add_friend","fb_like_post","fb_post_page","fb_message_page_inbox_customer","fb_join_group","fb_group_invite"],"log":"Proxy của tài khoản không kết nối được, tạm ngưng tài khoản tới {until}"}]'::jsonb) x,
      jsonb_array_elements_text(x->'actions') a, unnest(ARRAY['desktop', 'fly']) rt LOOP
    v_new := public.aka_agent_engine_resolve_policy(v_c->>'code', NULL, v_text, NULL, v_rt, 'before_send');
    IF v_new->>'target_effect' IS DISTINCT FROM 'requeue' OR v_new->>'target_streak_effect' IS DISTINCT FROM 'increment'
       OR (v_new->>'streak_threshold')::int IS DISTINCT FROM 4 OR v_new->>'campaign_effect' IS DISTINCT FROM 'pause'
       OR (v_new->>'lock_minutes')::int IS DISTINCT FROM 5 OR v_new->'lock_action_codes' IS DISTINCT FROM v_c->'actions'
       OR v_new->>'log_template' IS DISTINCT FROM v_c->>'log' OR v_new->>'quota_effect' IS DISTINCT FROM 'no_count' THEN
      RAISE EXCEPTION 'V659 postflight: % % % ra %', v_c->>'code', v_text, v_rt, v_new;
    END IF;
  END LOOP;
  FOR v_text, v_rt, v_c IN SELECT a, rt, to_jsonb(ph) FROM jsonb_array_elements_text('["zalo_find_phone_user","zalo_message_stranger","zalo_message_friend","zalo_message_group","zalo_add_friend","zalo_add_group_member","zalo_join_group","zalo_join_group_link","zalo_tag_contact","zalo_change_alias","zalo_cancel_sent_friend_request"]'::jsonb) a, unnest(ARRAY['desktop', 'fly']) rt,
      unnest(ARRAY['before_send', 'in_flight', 'after_send']) ph LOOP
    v_new := public.aka_agent_engine_resolve_policy('err_proxy_failed', NULL, v_text, NULL, v_rt, v_c #>> '{}');
    v_old := public.aka_agent_engine_resolve_policy('err_network_offline', NULL, v_text, NULL, v_rt, v_c #>> '{}');
    IF (v_new - 'policy_ids' - 'revisions' - 'error_class' - 'log_template' - 'campaign_note_template') IS DISTINCT FROM (v_old - 'policy_ids' - 'revisions' - 'error_class' - 'log_template' - 'campaign_note_template') OR v_new->>'log_template' IS DISTINCT FROM 'Proxy của tài khoản không kết nối được, tạm ngưng tài khoản tới {until}'
       OR v_old->>'log_template' IS DISTINCT FROM 'Kết nối mạng bị gián đoạn, tạm ngưng tài khoản tới {until}' THEN
      RAISE EXCEPTION 'V659 postflight: NET02 Zalo % % % khác NET01: % / %', v_text, v_rt, v_c, v_new, v_old;
    END IF;
  END LOOP;
  FOR v_c IN SELECT x FROM jsonb_array_elements('[{"action":"zalo_message_stranger","rt":"desktop","phase":"in_flight"},{"action":"zalo_message_stranger","rt":"desktop","phase":"before_send"},{"action":"zalo_message_stranger","rt":"desktop","phase":"after_send"},{"action":"zalo_message_stranger","rt":"fly","phase":"in_flight"},{"action":"zalo_message_stranger","rt":"fly","phase":"before_send"},{"action":"zalo_message_stranger","rt":"fly","phase":"after_send"},{"action":"zalo_message_friend","rt":"desktop","phase":"in_flight"},{"action":"zalo_message_friend","rt":"desktop","phase":"before_send"},{"action":"zalo_message_friend","rt":"desktop","phase":"after_send"},{"action":"zalo_message_friend","rt":"fly","phase":"in_flight"},{"action":"zalo_message_friend","rt":"fly","phase":"before_send"},{"action":"zalo_message_friend","rt":"fly","phase":"after_send"},{"action":"zalo_message_group","rt":"desktop","phase":"in_flight"},{"action":"zalo_message_group","rt":"desktop","phase":"before_send"},{"action":"zalo_message_group","rt":"desktop","phase":"after_send"},{"action":"zalo_message_group","rt":"fly","phase":"in_flight"},{"action":"zalo_message_group","rt":"fly","phase":"before_send"},{"action":"zalo_message_group","rt":"fly","phase":"after_send"},{"action":"zalo_add_friend","rt":"desktop","phase":"in_flight"},{"action":"zalo_add_friend","rt":"desktop","phase":"before_send"},{"action":"zalo_add_friend","rt":"desktop","phase":"after_send"},{"action":"zalo_add_friend","rt":"fly","phase":"in_flight"},{"action":"zalo_add_friend","rt":"fly","phase":"before_send"},{"action":"zalo_add_friend","rt":"fly","phase":"after_send"},{"action":"zalo_add_group_member","rt":"desktop","phase":"in_flight"},{"action":"zalo_add_group_member","rt":"desktop","phase":"before_send"},{"action":"zalo_add_group_member","rt":"desktop","phase":"after_send"},{"action":"zalo_add_group_member","rt":"fly","phase":"in_flight"},{"action":"zalo_add_group_member","rt":"fly","phase":"before_send"},{"action":"zalo_add_group_member","rt":"fly","phase":"after_send"},{"action":"zalo_join_group","rt":"desktop","phase":"in_flight"},{"action":"zalo_join_group","rt":"desktop","phase":"before_send"},{"action":"zalo_join_group","rt":"desktop","phase":"after_send"},{"action":"zalo_join_group","rt":"fly","phase":"in_flight"},{"action":"zalo_join_group","rt":"fly","phase":"before_send"},{"action":"zalo_join_group","rt":"fly","phase":"after_send"},{"action":"zalo_join_group_link","rt":"desktop","phase":"in_flight"},{"action":"zalo_join_group_link","rt":"desktop","phase":"before_send"},{"action":"zalo_join_group_link","rt":"desktop","phase":"after_send"},{"action":"zalo_join_group_link","rt":"fly","phase":"in_flight"},{"action":"zalo_join_group_link","rt":"fly","phase":"before_send"},{"action":"zalo_join_group_link","rt":"fly","phase":"after_send"},{"action":"zalo_tag_contact","rt":"desktop","phase":"in_flight"},{"action":"zalo_tag_contact","rt":"desktop","phase":"before_send"},{"action":"zalo_tag_contact","rt":"desktop","phase":"after_send"},{"action":"zalo_tag_contact","rt":"fly","phase":"in_flight"},{"action":"zalo_tag_contact","rt":"fly","phase":"before_send"},{"action":"zalo_tag_contact","rt":"fly","phase":"after_send"},{"action":"zalo_change_alias","rt":"desktop","phase":"in_flight"},{"action":"zalo_change_alias","rt":"desktop","phase":"before_send"},{"action":"zalo_change_alias","rt":"desktop","phase":"after_send"},{"action":"zalo_change_alias","rt":"fly","phase":"in_flight"},{"action":"zalo_change_alias","rt":"fly","phase":"before_send"},{"action":"zalo_change_alias","rt":"fly","phase":"after_send"},{"action":"zalo_cancel_sent_friend_request","rt":"desktop","phase":"in_flight"},{"action":"zalo_cancel_sent_friend_request","rt":"desktop","phase":"before_send"},{"action":"zalo_cancel_sent_friend_request","rt":"desktop","phase":"after_send"},{"action":"zalo_cancel_sent_friend_request","rt":"fly","phase":"in_flight"},{"action":"zalo_cancel_sent_friend_request","rt":"fly","phase":"before_send"},{"action":"zalo_cancel_sent_friend_request","rt":"fly","phase":"after_send"}]'::jsonb) x LOOP
    v_new := public.aka_agent_engine_resolve_policy('err_proxy_unknown_delivery', NULL, v_c->>'action', NULL, v_c->>'rt', v_c->>'phase');
    v_old := public.aka_agent_engine_resolve_policy('err_engine_unknown_delivery', NULL, v_c->>'action', NULL, v_c->>'rt', v_c->>'phase');
    IF (v_new - 'policy_ids' - 'revisions' - 'error_class' - 'log_template' - 'campaign_note_template') IS DISTINCT FROM (v_old - 'policy_ids' - 'revisions' - 'error_class' - 'log_template' - 'campaign_note_template') OR v_new->>'error_class' IS DISTINCT FROM 'unknown_delivery' THEN
      RAISE EXCEPTION 'V659 postflight: NET04 % khác UNK01: % / %', v_c, v_new, v_old;
    END IF;
  END LOOP;
  FOR v_c IN SELECT x FROM jsonb_array_elements('[{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_CONNECTION_TIMED_OUT (-118) loading ''https://www.facebook.com/groups/1''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_add_friend","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/profile.php","message":"ERR_CONNECTION_TIMED_OUT (-118) loading ''https://www.facebook.com/profile.php?id=1''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_CONNECTION_RESET (-101) loading ''https://www.facebook.com/groups/1''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_TIMED_OUT (-7) loading ''https://www.facebook.com/groups/1''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_SOCKET_NOT_CONNECTED (-15) loading ''https://www.facebook.com/groups/1''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_comment","phase":"before_send","signal":{"kind":"exception","message":"net::ERR_NAME_NOT_RESOLVED"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_NETWORK_IO_SUSPENDED (-331) loading ''https://www.facebook.com/groups/1''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_PROXY_CONNECTION_FAILED (-130) loading ''https://www.facebook.com/groups/1''"},"expected":"err_proxy_failed"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_TUNNEL_CONNECTION_FAILED (-111) loading ''https://www.facebook.com/groups/1''"},"expected":"err_proxy_failed"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com","message":"ERR_PROXY_CONNECTION_FAILED (-130) loading ''https://www.facebook.com/''"},"expected":"err_proxy_failed"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com","message":"ERR_TOO_MANY_RETRIES (-375) loading ''https://www.facebook.com/''"},"expected":"err_network_offline"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"identity_switch","errorCode":"err_fb_identity_switch_failed","message":"Không tìm thấy nút mở menu profile/page hiện tại"},"expected":"err_fb_identity_switch_failed"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"identity_switch","errorCode":"err_fb_identity_switch_failed","message":"ERR_PROXY_CONNECTION_FAILED (-130) loading ''https://www.facebook.com/''"},"expected":"err_fb_identity_switch_failed"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"wait:fb_post_button","message":"waitForSelector timeout: //div"},"expected":"err_engine_fb_ui_not_ready"},{"platform":"facebook","action":"fb_post_group","phase":"before_send","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_ABORTED (-3) loading ''https://www.facebook.com/groups/1''"},"expected":"err_engine_fb_ui_not_ready"},{"platform":"zalo","action":"zalo_find_phone_user","phase":"before_send","signal":{"kind":"message_like","message":"net::ERR_TUNNEL_CONNECTION_FAILED"},"expected":"err_proxy_failed"},{"platform":"zalo","action":"zalo_find_phone_user","phase":"before_send","signal":{"kind":"message_like","message":"net::ERR_PROXY_CONNECTION_FAILED"},"expected":"err_proxy_failed"},{"platform":"zalo","action":"zalo_message_stranger","phase":"before_send","signal":{"kind":"message_like","message":"fetch failed (read ECONNRESET)"},"expected":"err_network_offline"},{"platform":"zalo","action":"zalo_message_stranger","phase":"in_flight","signal":{"kind":"message_like","message":"net::ERR_TUNNEL_CONNECTION_FAILED"},"expected":"err_proxy_unknown_delivery"},{"platform":"zalo","action":"zalo_change_alias","phase":"in_flight","signal":{"kind":"message_like","message":"net::ERR_TUNNEL_CONNECTION_FAILED"},"expected":"err_proxy_unknown_delivery"},{"platform":"zalo","action":"zalo_add_friend","phase":"in_flight","signal":{"kind":"message_like","message":"request to https://tt-friend-wpa.chat.zalo.me/api/friend/sendreq failed, reason: Proxy connection ended before receiving CONNECT response"},"expected":"err_proxy_unknown_delivery"},{"platform":"zalo","action":"zalo_find_phone_user","phase":"in_flight","signal":{"kind":"message_like","message":"net::ERR_TUNNEL_CONNECTION_FAILED"},"expected":"err_proxy_failed"},{"platform":"zalo","action":"zalo_message_stranger","phase":"in_flight","signal":{"kind":"message_like","message":"fetch failed (read ECONNRESET)"},"expected":"err_engine_unknown_delivery"}]'::jsonb) x LOOP
    SELECT c.error_code INTO v_text FROM public.aka_agent_engine_classify_signal(v_c->>'platform', v_c->>'action', v_c->>'phase', v_c->'signal') c;
    IF v_text IS DISTINCT FROM v_c->>'expected' THEN RAISE EXCEPTION 'V659 postflight: tín hiệu % ra %', v_c, v_text; END IF;
  END LOOP;
  -- Lỗi mạng / proxy lúc đang gửi ở Facebook giữ như hôm nay.
  FOR v_c IN SELECT x FROM jsonb_array_elements('[{"platform":"facebook","action":"fb_post_group","phase":"in_flight","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_CONNECTION_RESET (-101) loading ''https://www.facebook.com/groups/1''"}},{"platform":"facebook","action":"fb_post_group","phase":"in_flight","signal":{"kind":"block","code":"navigate:www.facebook.com/groups/1","message":"ERR_PROXY_CONNECTION_FAILED (-130) loading ''https://www.facebook.com/groups/1''"}}]'::jsonb) x LOOP
    SELECT c.error_code INTO v_text FROM public.aka_agent_engine_classify_signal(v_c->>'platform', v_c->>'action', v_c->>'phase', v_c->'signal') c;
    IF v_text IN ('err_network_offline', 'err_proxy_failed', 'err_proxy_unknown_delivery') THEN RAISE EXCEPTION 'V659 postflight: tín hiệu % lúc đang gửi ra %', v_c, v_text; END IF;
  END LOOP;

  v_text := public.aka_agent_engine_wait_note('err_network_offline', timestamptz '2026-11-26 10:05:00+07');
  IF v_text IS DISTINCT FROM '⏳ Kết nối mạng bị gián đoạn, chạy tiếp lúc 10:05 26/11 (NET01)' THEN RAISE EXCEPTION 'V659 postflight: câu chờ NET01: %', v_text; END IF;
  v_text := public.aka_agent_engine_wait_note('err_proxy_failed', timestamptz '2026-11-26 10:05:00+07');
  IF v_text IS DISTINCT FROM '⏳ Proxy của tài khoản không kết nối được, chạy tiếp lúc 10:05 26/11 (NET02)' THEN
    RAISE EXCEPTION 'V659 postflight: câu chờ NET02: %', v_text;
  END IF;
END $post$;

COMMIT;
